<template><section class="log-page" v-loading="loading"><h2>{{titles[kind]}}</h2><template v-if="kind==='config'"><el-form label-width="180px"><el-form-item v-for="f in configFields" :key="f.key" :label="f.label"><el-input-number v-model="config[f.key]" :min="1" :max="f.key.endsWith('Ms')?600000:3650"/></el-form-item><el-form-item label="启用自动归档清理"><el-switch v-model="config.cleanupEnabled"/></el-form-item></el-form><p>待投递：{{config.pending}}　重试中：{{config.failedDeliveries}}　运行日志：{{config.runtimeCollected}}</p><p>最老待投递：{{config.oldestPendingTime||'—'}}　等待：{{config.oldestPendingSeconds||0}}秒　最近一分钟投递：{{config.deliveredLastMinute||0}}</p><el-button v-if="can('monitor:log-config:edit')" type="primary" @click="saveConfig">保存配置</el-button><h3>清理执行记录</h3><el-table :data="history" border><el-table-column label="日期" prop="businessDate"/><el-table-column label="结果" prop="status"/><el-table-column label="阶段" prop="stage"/><el-table-column label="操作日志已清理" prop="operationCount"/><el-table-column label="登录日志已清理" prop="loginCount"/><el-table-column label="运行日志已清理" prop="runtimeCount"/><el-table-column label="队列已清理" prop="outboxCount"/><el-table-column label="说明" prop="summary"/></el-table></template><template v-else><div class="log-toolbar"><el-popover v-model:visible="filterOpen" trigger="click" placement="bottom-start" :width="'min(1000px,94vw)'"><template #reference><el-button>筛选条件</el-button></template><div class="filters log-filter-panel"><el-date-picker v-model="range" type="datetimerange" value-format="YYYY-MM-DD HH:mm:ss" start-placeholder="开始时间" end-placeholder="结束时间"/><el-select v-if="kind==='operation'&&admin" v-model="query.factoryId" clearable placeholder="工厂"><el-option v-for="f in factories" :key="f.id" :label="f.name" :value="f.id"/></el-select><el-input v-if="kind!=='runtime'" v-model="query.actor" placeholder="操作账号"/><el-input v-if="kind==='operation'" v-model="query.module" placeholder="模块"/><el-select v-if="kind==='operation'" v-model="query.resultCode" clearable placeholder="结果"><el-option v-for="(name,value) in results" :key="value" :label="name" :value="value"/></el-select><el-input v-if="kind==='operation'" v-model="query.businessCode" placeholder="业务单号"/><el-select v-if="kind==='runtime'" v-model="query.level" clearable placeholder="日志级别"><el-option v-for="v in ['INFO','WARN','ERROR']" :key="v" :label="v" :value="v"/></el-select><el-input v-if="kind==='runtime'" v-model="query.component" placeholder="组件"/><el-input v-model="query.traceId" placeholder="追踪ID"/></div><div class="log-filter-actions"><el-button @click="resetFilters">重置</el-button><el-button type="primary" @click="applyFilters">查询</el-button></div></el-popover><el-button type="primary" @click="applyFilters">查询</el-button><el-button v-if="can(exportPermission)" :loading="exporting" @click="exportLogs">导出</el-button></div><el-table :data="rows" border><el-table-column v-for="c in columns" :key="c.key" :label="c.label" :prop="c.key" :min-width="c.width||110"><template #default="{row}">{{c.key==='resultCode'?results[row[c.key]]||row[c.key]:kind==='login'&&c.key==='status'?(row[c.key]==='0'?'成功':'失败'):row[c.key]??'—'}}</template></el-table-column><el-table-column v-if="kind!=='login'&&can(detailPermission)" label="操作" width="85"><template #default="{row}"><el-button link type="primary" @click="view(row)">详情</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="query.pageNum" :page-size="16" :total="total" layout="total,prev,pager,next" @current-change="load"/></template><el-dialog v-model="detailOpen" title="日志详情" width="min(950px,94vw)"><div class="log-details"><template v-for="(value,key) in detail" :key="key"><strong>{{fieldNames[key]||key}}</strong><pre>{{format(value)}}</pre></template></div><template #footer><el-button @click="copyTrace">复制追踪ID</el-button><el-button @click="detailOpen=false">关闭</el-button></template></el-dialog></section></template>
<script setup lang="ts">
import {copyText} from '@/utils/clipboard'
import{computed,onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import request from'@/utils/request';import{download}from'@/utils/request';import useUserStore from'@/store/modules/user';
const props=defineProps<{kind:string}>(),kind=props.kind,user=useUserStore(),admin=computed(()=>String(user.id)==='1'),can=(p:string)=>user.permissions.includes('*:*:*')||user.permissions.includes(p);const titles:Record<string,string>={operation:'操作日志',login:'登录日志',runtime:'系统运行日志',config:'日志配置'},roots:Record<string,string>={operation:'/monitor/operlog',login:'/monitor/logininfor',runtime:'/monitor/runtime-log'},permissions:Record<string,string>={operation:'monitor:operlog',login:'monitor:logininfor',runtime:'monitor:runtime-log'};const detailPermission=permissions[kind]+':query',exportPermission=permissions[kind]+':export';const results:Record<string,string>={SUCCESS:'成功',BUSINESS_REJECTED:'业务拒绝',VALIDATION_REJECTED:'校验失败',ACCESS_DENIED:'无权限',SYSTEM_ERROR:'系统异常'};
const factories=ref<any[]>([]),filterOpen=ref(false),exporting=ref(false),appliedFilters=ref<Record<string,any>>({});
const query=reactive<Record<string,any>>({pageNum:1,pageSize:16}),range=ref<string[]|null>([]),rows=ref<any[]>([]),total=ref(0),loading=ref(false),detailOpen=ref(false),detail=ref<Record<string,any>>({}),config=reactive<Record<string,any>>({}),history=ref<any[]>([]);
const c=(label:string,key:string,width?:number)=>({label,key,width});const columns=kind==='operation'?[c('时间','operTime',155),c('工厂','factoryName'),c('操作人','actorName'),c('模块','title'),c('操作类型','actionCode'),c('业务单号','businessCode',150),c('结果','resultCode'),c('耗时(ms)','costTime',90),c('追踪ID','traceId',245)]:kind==='login'?[c('账号','userName'),c('时间','loginTime',155),c('结果','status'),c('原因','msg',220),c('来源IP','ipaddr'),c('浏览器','browser'),c('追踪ID','traceId',245)]:[c('时间','eventTime',155),c('级别','level',70),c('服务','service'),c('组件','component',180),c('事件','eventType'),c('摘要','summary',240),c('追踪ID','traceId',245)];
const fieldNames:Record<string,string>={operParam:'请求摘要',jsonResult:'响应摘要',changesJson:'字段变更（前后快照）',errorMsg:'失败原因',traceId:'追踪ID',businessCode:'业务单号',detailJson:'技术定位',actorName:'操作人',factoryName:'工厂'};const configFields=[{key:'operationDays',label:'操作日志保留（天）'},{key:'loginDays',label:'登录日志保留（天）'},{key:'runtimeDays',label:'运行日志保留（天）'},{key:'fileDays',label:'运行文件保留（天）'},{key:'archiveDays',label:'审计归档保留（天）'},{key:'slowRequestMs',label:'慢请求阈值(ms)'},{key:'slowSqlMs',label:'慢SQL阈值(ms)'}];
function draftParams(){const result:Record<string,any>={...query,startTime:range.value?.[0],endTime:range.value?.[1]};delete result.pageNum;delete result.pageSize;return Object.fromEntries(Object.entries(result).filter(([,v])=>v!==undefined&&v!==null&&v!==''))}
function params(){return{...appliedFilters.value,pageNum:query.pageNum,pageSize:query.pageSize}}
function applyFilters(){if(range.value?.length===2&&range.value[0]>range.value[1]){ElMessage.warning('开始时间不能晚于结束时间');return}appliedFilters.value=draftParams();query.pageNum=1;filterOpen.value=false;load()}
function resetFilters(){for(const key of Object.keys(query))if(!['pageNum','pageSize'].includes(key))delete query[key];range.value=[];applyFilters()}
async function load(){loading.value=true;try{if(kind==='config'){Object.assign(config,(await request({url:'/monitor/log-config'})).data);configFields.forEach(f=>config[f.key]=Number(config[f.key]));history.value=(await request({url:'/monitor/log-config/cleanup-history'})).data;}else{const r=await request({url:roots[kind]+'/list',params:params()});rows.value=r.rows;total.value=Number(r.total)}}finally{loading.value=false}}
async function view(row:any){detail.value=(await request({url:roots[kind]+'/'+(row.id||row.operId)})).data;detailOpen.value=true}function format(value:any){if(typeof value==='string'){try{return JSON.stringify(JSON.parse(value),null,2)}catch{return value}}return JSON.stringify(value,null,2)}async function copyTrace(){if(detail.value.traceId){try{await copyText(detail.value.traceId);ElMessage.success('追踪ID已复制')}catch{ElMessage.warning('复制失败，请手动选择追踪ID')}}}async function exportLogs(){if(exporting.value)return;if(JSON.stringify(draftParams())!==JSON.stringify(appliedFilters.value)){ElMessage.warning('筛选条件已修改，请先点击查询');return}exporting.value=true;try{await download(roots[kind]+'/export',params(),'日志.xlsx')}finally{exporting.value=false}}async function saveConfig(){await request({url:'/monitor/log-config',method:'put',data:config});ElMessage.success('配置已保存');await load()}onMounted(async()=>{if(kind==='operation'&&admin.value)factories.value=(await request({url:'/metal/work-order/options/factories'})).data;await load()})
</script><style scoped>.log-page{padding:20px;min-height:calc(100vh - 82px)}h2{font-size:20px;margin:0 0 20px}.log-toolbar{display:flex;align-items:center;gap:12px;flex-wrap:nowrap;overflow-x:auto;margin-bottom:18px}.log-toolbar>*{flex-shrink:0}.log-toolbar .el-button{margin:0}.log-filter-panel{max-height:55vh;overflow:auto}.log-filter-actions{display:flex;justify-content:flex-end;gap:10px}.filters{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:18px}.filters .el-input,.filters .el-select{width:180px}.el-pagination{justify-content:center;margin-top:24px}.log-details{display:grid;grid-template-columns:150px 1fr;gap:12px;max-height:65vh;overflow:auto}.log-details pre{white-space:pre-wrap;overflow-wrap:anywhere;margin:0;font-size:13px}</style>
